package com.commercecore.order;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.web.bind.annotation.*;import java.net.URI;import java.util.UUID;@RestController@RequestMapping("/api/v1/checkout")@SecurityRequirement(name="bearerAuth")public class CheckoutController{private final OrderService orders;public CheckoutController(OrderService o){orders=o;}@PostMapping ResponseEntity<OrderDtos.OrderResponse>checkout(@AuthenticationPrincipal Jwt jwt,@RequestHeader("Idempotency-Key")String key,@Valid@RequestBody OrderDtos.CheckoutRequest request){OrderDtos.OrderResponse result=orders.checkout(UUID.fromString(jwt.getSubject()),key,request);return ResponseEntity.created(URI.create("/api/v1/orders/"+result.id())).body(result);}}
